PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
ASK {
  VALUES ?school1Name { "North Marion High School (Oregon)" }
  VALUES ?school2Name { "Seoul High School" }
  ?school1 (rdfs:label|skos:altLabel) ?school1Name .
  ?school2 (rdfs:label|skos:altLabel) ?school2Name .
  ?school1 <http://example.org/2wiki-ontology#hasCountry> ?c .
  ?school2 <http://example.org/2wiki-ontology#hasCountry> ?c .
}

SELECT ?answer WHERE {
  { ?person rdfs:label "Jean Martin" . }
  UNION
  { ?person skos:altLabel "Jean Martin (singer)" . }
  ?person <http://example.org/2wiki-ontology#hasSpouse> ?spouse .
  ?spouse <http://example.org/2wiki-ontology#hasDeathDate> ?answer .
}

SELECT DISTINCT ?answer WHERE {
  ?song <http://www.w3.org/2000/01/rdf-schema#label> "Sunday Papers" .
  ?song <http://example.org/2wiki-ontology#hasPerformer> ?performer .
  ?performer <http://example.org/2wiki-ontology#hasAwardReceived> ?award .
  ?award <http://www.w3.org/2000/01/rdf-schema#label> ?answer .
}

SELECT ?answer WHERE {
  ?person rdfs:label "Benjamin Weinman" .
  ?person <http://example.org/2wiki-ontology#hasBirthDate> ?answer .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  ?dexter rdfs:label "Dexter Young" .
  ?dexter ex:hasMother ?mother .
  { ?mother ex:hasCitizenship ?country }
  UNION { ?mother ex:hasNationality ?country }
  UNION { ?mother ex:hasCountry ?country }
  ?country rdfs:label ?answer .
}
LIMIT 1

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  ?film1 rdfs:label "Ami Neta Hobo" ;
          ex:hasPublicationDate ?date1 .
  ?film2 rdfs:label "Hood of the Living Dead" ;
          ex:hasPublicationDate ?date2 .
  BIND( IF(?date1 <= ?date2, "Ami Neta Hobo", "Hood of the Living Dead") AS ?answer )
}

SELECT DISTINCT ?answer WHERE {
  ?song <http://www.w3.org/2000/01/rdf-schema#label> "Oh boy, oh boy, oh boy!" .
  ?song <http://example.org/2wiki-ontology#hasPerformer> ?person .
  ?person <http://example.org/2wiki-ontology#hasCauseOfDeath> ?cause .
  ?cause <http://www.w3.org/2000/01/rdf-schema#label> ?answer .
}

PREFIX ex: <http://example.org/2wiki-ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?answer WHERE {
  ?catherine rdfs:label "Catherine Allégret" .
  ?catherine (ex:hasFather|ex:hasMother)/ex:hasBrother ?answer .
}

ASK WHERE {
  ?place1 <http://www.w3.org/2000/01/rdf-schema#label> "Coal City, Illinois" .
  ?place2 <http://www.w3.org/2000/01/rdf-schema#label> "Lash Kenar, Nur" .
  ?place1 <http://example.org/2wiki-ontology#hasCountry> ?country .
  ?place2 <http://example.org/2wiki-ontology#hasCountry> ?country .
