SELECT ?answer WHERE {
  ?film rdfs:label "Los Motivos de Luz" .
  ?film <http://example.org/2wiki-ontology#hasDirector> ?director .
  ?director <http://example.org/2wiki-ontology#hasBirthPlace> ?place .
  ?place rdfs:label ?answer .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  {
    SELECT ?label ( (YEAR(xsd:dateTime(?death)) - YEAR(xsd:dateTime(?birth))) AS ?age )
    WHERE {
      ?person rdfs:label ?label .
      FILTER(?label = "Louis-Armand-Constantin de Rohan" || ?label = "Adalberto Pereira dos Santos")
      ?person ex:hasBirthDate ?birth .
      ?person ex:hasDeathDate ?death .
    }
  }
  BIND(?label AS ?answer)
}
ORDER BY DESC(?age)
LIMIT 1

PREFIX ex: <http://example.org/2wiki-ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?answer WHERE {
  {
    SELECT ?org ?date ?label WHERE {
      ?org a ex:Organization ;
           rdfs:label ?label ;
           ex:hasInception ?date .
      FILTER (?label = "BESIX" || ?label = "Circus Herman Renz")
    }
  }
  BIND(?label AS ?answer)
}
ORDER BY ASC(?date)
LIMIT 1

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  ?ealdorman rdfs:label "Æthelwald" .
  ?ealdorman ex:hasSpouse ?wife .
  ?wife rdfs:label "Ælfthryth" .
  { ?wife ex:hasCitizenship ?c . }
  UNION
  { ?wife ex:hasNationality ?c . }
  ?c rdfs:label ?answer .
}

SELECT DISTINCT ?answer WHERE {
  ?film a <http://example.org/2wiki-ontology#Film> ;
        rdfs:label "Mary Jane's Pa" ;
        <http://example.org/2wiki-ontology#hasDirector> ?director .
  ?director <http://example.org/2wiki-ontology#hasDeathPlace> ?place .
  ?place rdfs:label ?answer .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  {
    SELECT ?film ?filmLabel ?death WHERE {
      ?film a ex:CreativeWork .
      ?film (rdfs:label|skos:altLabel) ?filmLabel .
      FILTER(
        ?filmLabel = "The Criminal"@en ||
        ?filmLabel = "The Criminal (1960 film)"@en ||
        ?filmLabel = "A Soldier's Oath"@en
      ) .
      ?film ex:hasProducer ?producer .
      ?producer ex:hasDeathDate ?death .
    }
    ORDER BY ?death
    LIMIT 1
  }
  BIND(?filmLabel AS ?answer)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/2wiki-ontology#>
SELECT ?answer WHERE {
  {
    SELECT ?filmLabel ?birthDate WHERE {
      VALUES ?filmTitle { "Term Life" "Housefull 2" }
      ?film rdfs:label ?filmTitle .
      ?film ex:hasProducer ?producer .
      ?producer ex:hasBirthDate ?birthDate .
      BIND(?filmTitle AS ?filmLabel)
    }
    ORDER BY ?birthDate
    LIMIT 1
  }
  BIND(?filmLabel AS ?answer)
}
